sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-rooms-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 55px 25px 75px;
  color: #2a2d29;
  font-family: Arial, sans-serif;
}

.rooms-heading {
  text-align: center;
  margin-bottom: 40px;
}

.rooms-eyebrow,
.empty-eyebrow {
  color: #a8875b;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
}

.rooms-heading h1 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 42px;
  margin: 12px 0;
}

.rooms-heading p {
  color: #6f756f;
  font-size: 15px;
}

.rooms-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
  gap: 25px;
}

.room-card {
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 12px;
  box-shadow: 0 5px 20px rgba(31, 58, 48, 0.06);
}

.room-image {
  height: 190px;
  position: relative;
  background: linear-gradient(135deg, #d8e0d8, #aabdaf);
}

.room-type {
  position: absolute;
  top: 15px;
  left: 15px;
  background: #ffffff;
  color: #1f3a30;
  padding: 7px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
}

.room-content {
  padding: 22px;
}

.room-content h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 23px;
  margin: 0 0 18px;
}

.room-details {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  color: #6f756f;
  font-size: 12px;
}

.room-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid #e7e1d4;
  margin-top: 22px;
  padding-top: 18px;
}

.room-price strong {
  display: block;
  color: #1f3a30;
  font-size: 18px;
}

.room-price small {
  color: #6f756f;
  font-size: 11px;
}

.book-button,
.empty-button {
  display: inline-block;
  background: #1f3a30;
  color: #ffffff !important;
  padding: 11px 16px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none !important;
}

.book-button:hover,
.empty-button:hover {
  background: #162a22;
}

.rooms-empty {
  max-width: 650px;
  margin: 35px auto 20px;
  padding: 55px 30px;
  text-align: center;
  background: #faf6ef;
  border: 1px solid #e7e1d4;
  border-radius: 14px;
}

.empty-icon {
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 22px;
  background: #e8eee9;
  color: #1f3a30;
  border-radius: 50%;
  font-size: 27px;
}

.rooms-empty h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 29px;
  margin: 12px 0;
}

.rooms-empty p {
  max-width: 440px;
  margin: 0 auto 25px;
  color: #6f756f;
  font-size: 14px;
  line-height: 1.8;
}

@media (max-width: 600px) {
  .hotel-rooms-page {
    padding: 35px 15px 50px;
  }

  .rooms-heading h1 {
    font-size: 32px;
  }

  .room-bottom {
    align-items: flex-start;
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
    data.rooms = [];

    var gr = new GlideRecordSecure('x_2206701_hotel_0_rooms');
    gr.orderBy('room_name');
    gr.query();

    while (gr.next()) {
        data.rooms.push({
            sys_id: gr.getUniqueValue(),
            name: gr.getDisplayValue('room_name'),
            type: gr.getDisplayValue('room_type'),
            capacity: gr.getDisplayValue('capacity'),
            rate: gr.getDisplayValue('rate'),
            availability: gr.getDisplayValue('availability_status')
        });
    }
})();
